-- ======================= BU VN =======================
CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_vn.src_customer
COMMENT 'Raw customer extract landed from LifeAsia (VN) (simulated Lakeflow Connect ingestion)' AS
WITH b AS (SELECT id FROM range(60000)),
x AS (SELECT id, CASE WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 0.050 THEN NULL WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 0.100 THEN '   ' WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 0.400 THEN concat(lower('VN'), lpad(cast(id + 100001 AS STRING), 7, '0')) WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 0.440 THEN concat('VN', lpad(cast(id + 100000 AS STRING), 9, '0')) ELSE concat('VN', lpad(cast(id + 100001 AS STRING), 9, '0')) END AS CUST_NO, CASE WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 0.200 THEN NULL WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 0.600 THEN 'ACT' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 62.600 THEN 'ACTIVE' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 77.600 THEN 'INACTIVE' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 90.600 THEN 'LAPSED' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 93.600 THEN 'DECEASED' ELSE 'PROSPECT' END AS CUST_STAT, CASE WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 0.600 THEN NULL WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 1.400 THEN 'OTHER' WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 2.100 THEN 'UNKNOWN' WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 2.400 THEN 'Viet Nam' WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 11.400 THEN element_at(array('SG','CN','HK','TH','ID','IN','US','GB','AU','JP','KR','TW'), cast(pmod(xxhash64(id,'fn'), 12) AS INT) + 1) ELSE 'VN' END AS NATL, CASE WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 0.300 THEN NULL WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 1.020 THEN 'OTHER' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 1.500 THEN 'UNKNOWN' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 59.500 THEN 'CCCD' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 73.500 THEN 'NATIONAL_ID' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 95.500 THEN 'PASSPORT' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 98.500 THEN 'BIRTH_CERT' ELSE 'PASSPORT' END AS ID_TYPE, CASE WHEN (pmod(xxhash64(id, 'dob'), 100000) / 1000.0) < 0.300 THEN NULL WHEN (pmod(xxhash64(id, 'dob'), 100000) / 1000.0) < 0.400 THEN '18990101' WHEN (pmod(xxhash64(id, 'dob'), 100000) / 1000.0) < 0.500 THEN '20991231' ELSE date_format(date_add(DATE'1950-01-01', cast(pmod(xxhash64(id,'dob'), 20000) AS INT)), 'yyyyMMdd') END AS BIRTH_DT, CASE WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 0.200 THEN NULL WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 0.400 THEN 'X' WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 49.400 THEN 'M' WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 98.400 THEN 'F' ELSE 'U' END AS SEX, CAST(NULL AS STRING) AS TIN FROM b)
SELECT id AS SRC_ROW_ID, CUST_NO, CUST_STAT, NATL,
  CASE WHEN (pmod(xxhash64(id, 'ns'), 100000) / 1000.0) < 0.5 THEN NULL WHEN NATL = 'VN' THEN 'CITIZEN' WHEN (pmod(xxhash64(id, 'ns2'), 100000) / 1000.0) < 30 THEN 'PERMANENT_RESIDENT' ELSE 'FOREIGNER' END AS NATL_STAT,
  ID_TYPE,
  CASE WHEN ID_TYPE = 'CCCD' AND (pmod(xxhash64(id, 'cccd'), 100000) / 1000.0) < 1.5 THEN lpad(cast(pmod(xxhash64(id,'cn'),1000000000) AS STRING), 9, '0')
       WHEN ID_TYPE = 'CCCD' THEN concat('0', lpad(cast(pmod(xxhash64(id,'cn'),100000000000) AS STRING), 11, '0'))
       WHEN ID_TYPE IS NULL THEN NULL
       ELSE upper(substr(sha2(cast(id AS STRING), 256), 1, 9)) END AS ID_NO,
  BIRTH_DT, SEX, TIN, 'LifeAsia (VN)' AS SRC_SYS, TIMESTAMP'2026-11-01 02:00:00' AS LOAD_TS
FROM x;

CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_vn.src_policy
COMMENT 'Raw policy extract landed from LifeAsia (VN) (simulated Lakeflow Connect ingestion)' AS
SELECT
  CASE WHEN (pmod(xxhash64(SRC_ROW_ID * 10 + pno, 'pn'), 100000) / 1000.0) < 0.05 THEN NULL
       ELSE concat('PVN', lpad(cast((SRC_ROW_ID * 10 + pno + CASE WHEN (pmod(xxhash64(SRC_ROW_ID * 10 + pno, 'pd'), 100000) / 1000.0) < 0.08 THEN -1 ELSE 0 END) AS STRING), 10, '0')) END AS POL_NO,
  CUST_NO,
  CASE WHEN (pmod(xxhash64(SRC_ROW_ID * 10 + pno, 'pb'), 100000) / 1000.0) < 0.2 THEN 'XX'
       WHEN pno = 1 AND CUST_STAT = 'ACTIVE' AND (pmod(xxhash64(SRC_ROW_ID, 'cs'), 100000) / 1000.0) >= 1.1 THEN 'IF'
       WHEN pno = 1 AND CUST_STAT = 'ACTIVE' THEN 'LA'
       WHEN CUST_STAT = 'ACTIVE' THEN element_at(array('IF','IF','LA','MA'), cast(pmod(xxhash64(SRC_ROW_ID, pno), 4) AS INT) + 1)
       ELSE element_at(array('LA','SU','MA','CL'), cast(pmod(xxhash64(SRC_ROW_ID, pno), 4) AS INT) + 1) END AS POL_STAT,
  element_at(array('WL01','TL10','ILP3','HS02','CI05'), cast(pmod(xxhash64(SRC_ROW_ID, pno, 'prd'), 5) AS INT) + 1) AS PRD_CD,
  date_add(DATE'2008-01-01', cast(pmod(xxhash64(SRC_ROW_ID, pno, 'iss'), 6500) AS INT)) AS ISS_DT,
  'LifeAsia (VN)' AS SRC_SYS
FROM (SELECT SRC_ROW_ID, CUST_NO, CUST_STAT, explode(sequence(1, 1 + cast(pmod(xxhash64(SRC_ROW_ID,'np'), 3) AS INT))) AS pno FROM ${catalog}.${prefix}_bu_vn.src_customer);

CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_vn.customer
COMMENT 'Curated customer (standardised codes, typed dates)' AS
SELECT SRC_ROW_ID AS src_row_id, CUST_NO AS customer_id, upper(trim(CUST_STAT)) AS current_status, NATL AS nationality,
       NATL_STAT AS nationality_status, ID_TYPE AS id_doc_type, ID_NO AS id_doc_no,
       try_to_date(BIRTH_DT, 'yyyyMMdd') AS date_of_birth, SEX AS gender, TIN AS tin, SRC_SYS AS source_system, LOAD_TS AS load_ts
FROM ${catalog}.${prefix}_bu_vn.src_customer;

CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_vn.policy
COMMENT 'Curated policy' AS
SELECT POL_NO AS policy_no, CUST_NO AS customer_id, POL_STAT AS policy_status, PRD_CD AS product_code, ISS_DT AS issue_date, SRC_SYS AS source_system
FROM ${catalog}.${prefix}_bu_vn.src_policy;

CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_vn.dq_customer_mart
COMMENT 'BU VN DQ data mart - customer grain. Prepared by the BU for monthly DQ assessment.' AS
SELECT c.src_row_id, c.customer_id, c.current_status, c.nationality, c.nationality_status, c.id_doc_type, c.id_doc_no,
       c.date_of_birth, c.gender, c.tin, coalesce(p.policy_count, 0) AS policy_count, coalesce(p.active_policy_count, 0) AS active_policy_count,
       c.source_system, 'VN' AS bu_code, DATE'2026-10-31' AS as_of_date
FROM ${catalog}.${prefix}_bu_vn.customer c
LEFT JOIN (SELECT customer_id, count(*) AS policy_count, count_if(policy_status = 'IF') AS active_policy_count FROM ${catalog}.${prefix}_bu_vn.policy GROUP BY customer_id) p
  ON c.customer_id = p.customer_id;

CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_vn.dq_policy_mart
COMMENT 'BU VN DQ data mart - policy grain' AS
SELECT row_number() OVER (ORDER BY customer_id, issue_date) AS src_row_id, policy_no, customer_id, policy_status, product_code, issue_date, source_system,
       'VN' AS bu_code, DATE'2026-10-31' AS as_of_date
FROM ${catalog}.${prefix}_bu_vn.policy;

-- standard-format intake tables (filled by the BU; shared to the Group workspace)
CREATE TABLE IF NOT EXISTS ${catalog}.${prefix}_bu_vn.intake_data_elements (
  batch_id STRING, submitted_by STRING, submitted_at TIMESTAMP,
  de_id STRING, name STRING, description STRING, status STRING, cde_flag BOOLEAN, subject_area STRING, data_domain STRING,
  data_subdomain STRING, defined_by STRING, de_type STRING, parent_de_id STRING, physical_table STRING, physical_column STRING
) COMMENT 'BU VN standard-format data element submissions (Group template v1)';
CREATE TABLE IF NOT EXISTS ${catalog}.${prefix}_bu_vn.intake_dq_rules (
  batch_id STRING, submitted_by STRING, submitted_at TIMESTAMP,
  rule_id STRING, name STRING, status STRING, dq_dimension STRING, description STRING, defined_by STRING, applicable_to STRING,
  parent_rule_id STRING, rule_type STRING, rule_params STRING, threshold_pct DOUBLE
) COMMENT 'BU VN standard-format DQ rule submissions (Group template v1)';


