CREATE OR REPLACE TABLE ${catalog}.${prefix}_bu_ph.src_customer
COMMENT 'Raw customer extract landed from Ingenium (PH) (simulated Lakeflow Connect ingestion)' AS
WITH b AS (SELECT id FROM range(50000)),
x AS (SELECT id, CASE WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 0.200 THEN NULL WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 0.500 THEN '   ' WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 2.100 THEN concat(lower('PH-'), lpad(cast(id + 100001 AS STRING), 6, '0')) WHEN (pmod(xxhash64(id, 'cid'), 100000) / 1000.0) < 2.250 THEN concat('PH-', lpad(cast(id + 100000 AS STRING), 8, '0')) ELSE concat('PH-', lpad(cast(id + 100001 AS STRING), 8, '0')) END AS CUST_NO, CASE WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 0.900 THEN NULL WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 2.400 THEN 'ACT' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 64.400 THEN 'ACTIVE' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 79.400 THEN 'INACTIVE' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 92.400 THEN 'LAPSED' WHEN (pmod(xxhash64(id, 'stat'), 100000) / 1000.0) < 95.400 THEN 'DECEASED' ELSE 'PROSPECT' END AS CUST_STAT, CASE WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 1.800 THEN NULL WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 3.000 THEN 'OTHER' WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 5.100 THEN 'UNKNOWN' WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 6.000 THEN 'N/A' WHEN (pmod(xxhash64(id, 'natl'), 100000) / 1000.0) < 15.000 THEN element_at(array('SG','CN','HK','TH','ID','IN','US','GB','AU','JP','KR','TW'), cast(pmod(xxhash64(id,'fn'), 12) AS INT) + 1) ELSE 'PH' END AS NATL, CASE WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 1.100 THEN NULL WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 2.660 THEN 'OTHER' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 3.700 THEN 'UNKNOWN' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 33.700 THEN 'UMID' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 61.700 THEN 'NATIONAL_ID' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 87.700 THEN 'PASSPORT' WHEN (pmod(xxhash64(id, 'idt'), 100000) / 1000.0) < 99.700 THEN 'DRIVING_LICENCE' ELSE 'PASSPORT' END AS ID_TYPE, CASE WHEN (pmod(xxhash64(id, 'dob'), 100000) / 1000.0) < 0.800 THEN NULL WHEN (pmod(xxhash64(id, 'dob'), 100000) / 1000.0) < 1.100 THEN '18990101' WHEN (pmod(xxhash64(id, 'dob'), 100000) / 1000.0) < 1.400 THEN '20991231' ELSE date_format(date_add(DATE'1950-01-01', cast(pmod(xxhash64(id,'dob'), 20000) AS INT)), 'yyyyMMdd') END AS BIRTH_DT, CASE WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 0.500 THEN NULL WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 1.000 THEN 'X' WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 50.000 THEN 'M' WHEN (pmod(xxhash64(id, 'sex'), 100000) / 1000.0) < 99.000 THEN 'F' ELSE 'U' END AS SEX, CASE WHEN (pmod(xxhash64(id, 'tin'), 100000) / 1000.0) < 2.500 THEN NULL WHEN (pmod(xxhash64(id, 'tin'), 100000) / 1000.0) < 4.300 THEN cast(pmod(xxhash64(id,'t4'),100000) AS STRING) ELSE concat(lpad(cast(pmod(xxhash64(id,'t1'),1000) AS STRING),3,'0'),'-',lpad(cast(pmod(xxhash64(id,'t2'),1000) AS STRING),3,'0'),'-',lpad(cast(pmod(xxhash64(id,'t3'),1000) AS STRING),3,'0')) END AS TIN FROM b)
SELECT id AS SRC_ROW_ID, CUST_NO, CUST_STAT, NATL,
  CASE WHEN (pmod(xxhash64(id, 'ns'), 100000) / 1000.0) < 2.4 THEN NULL WHEN NATL = 'PH' THEN 'CITIZEN' WHEN (pmod(xxhash64(id, 'ns2'), 100000) / 1000.0) < 30 THEN 'PERMANENT_RESIDENT' ELSE 'FOREIGNER' END AS NATL_STAT,
  ID_TYPE,
  CASE WHEN ID_TYPE = 'CCCD' AND (pmod(xxhash64(id, 'cccd'), 100000) / 1000.0) < 0 THEN lpad(cast(pmod(xxhash64(id,'cn'),1000000000) AS STRING), 9, '0')
       WHEN ID_TYPE = 'CCCD' THEN concat('0', lpad(cast(pmod(xxhash64(id,'cn'),100000000000) AS STRING), 11, '0'))
       WHEN ID_TYPE IS NULL THEN NULL
       ELSE upper(substr(sha2(cast(id AS STRING), 256), 1, 9)) END AS ID_NO,
  BIRTH_DT, SEX, TIN, 'Ingenium (PH)' AS SRC_SYS, TIMESTAMP'2026-11-01 02:00:00' AS LOAD_TS
FROM x;

